  /\ rdn ASEGS MV (Z_to_bv 64 6791384) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 tid)) /\ 1 <= tid <= 4194303
  /\ (forall i, 0x1423d0 <= i < 0x142a10 -> MV (Z_to_bv 64 i) = None).


